head.script:
/* ★Wcraft guide★    
스크립트 수작업 유의사항
eval함수는 자동변환에 제약이 많습니다. ASIS소스 확인 후 변환해주세요.
eval함수 사용 수: 2

*/

scwin.contnId;
scwin.objTpCd;
scwin.vCurDate;
scwin.gLdMktTp = js_market;

///////// 2. 초기화 영역 /////////
scwin.onpageload = function() {
};

scwin.onpageunload = function() {
};

///////// 3. 컴포넌트 이벤트 영역 /////////
scwin.btn_save_onclick = function() {
    try {
        if (scwin.contnId === "input") {
            scwin.save();
        } else {
            scwin.update();
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDMGT42045.btn_save_onclick" });
    }
};

scwin.trs_Save_OnSuccess = async function() {
    try {
        alert($c.data.getMessage("MSG-A001", "도움말등록"));
        await $c.win.closePopup();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDMGT42045.trs_Save_OnSuccess" });
    }
};

scwin.trs_Save_OnFail = function() {
    try {
        alert($c.data.getMessage("MSG-A002", "도움말등록"));
        alert(trs_Save.ErrorMsg);
        // alert(dts_C_All.ErrorMsg);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDMGT42045.trs_Save_OnFail" });
    }
};

scwin.trs_Update_OnSuccess = async function() {
    try {
        alert($c.data.getMessage("MSG-A001", "도움말수정"));
        await $c.win.closePopup();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDMGT42045.trs_Update_OnSuccess" });
    }
};

scwin.trs_Update_OnFail = function() {
    try {
        alert($c.data.getMessage("MSG-A002", "도움말수정"));
        alert(trs_Update.ErrorMsg);
        // alert(dts_C_All.ErrorMsg);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDMGT42045.trs_Update_OnFail" });
    }
};

scwin.trs_Delete_OnSuccess = async function() {
    try {
        alert($c.data.getMessage("MSG-A001", "도움말삭제"));
        await $c.win.closePopup();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDMGT42045.trs_Delete_OnSuccess" });
    }
};

scwin.trs_Delete_OnFail = function() {
    try {
        alert($c.data.getMessage("MSG-A002", "도움말삭제"));
        alert(trs_Delete.ErrorMsg);
        // alert(dts_C_All.ErrorMsg);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDMGT42045.trs_Delete_OnFail" });
    }
};

scwin.inf_find_OnClick = function() {
    try {
        const filenm = file_name.value;
        dts_fileList.setCellData(dts_fileList.getRowPosition(), "fileInfo", inf_find.Value);
        file_name.setValue(inf_find.Value);
        if (inf_find.Value === "") {
            file_name.setValue(filenm);
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDMGT42045.inf_find_OnClick" });
    }
};

scwin.btn_cancel_onclick = async function() {
    try {
        await $c.win.closePopup();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDMGT42045.btn_cancel_onclick" });
    }
};

scwin.topmenusearch_OnFilter = function(row) {
    try {
        f1 = topmenusearch.getCellData(row, "MENU_NM");
        if (f1.indexOf(cmb_QuickMenu_scren.getText()) !== -1) {
            return true;
        } else {
            return false;
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDMGT42045.topmenusearch_OnFilter" });
    }
};

scwin.cmb_QuickMenu_scren_OnCloseUp = function() {
    try {
        const selval = cmb_QuickMenu_scren.getText();
        if (selval !== "화면명검색") {
            e = selval.split("_");
            if (e.length > 1) {
                cmb_QuickMenu_scren.setSelectedIndex(-1);
                ipt_scren_id.setValue(e[1].toString());
                ipt_scren_nm.setValue(e[0].toString());
            }
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDMGT42045.cmb_QuickMenu_scren_OnCloseUp" });
    }
};

scwin.cmb_QuickMenu_scren_OnKeyDown = function(keycode) {
    try {
        if (keycode === '13') {
            scwin.topmenusearchEnter();
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDMGT42045.cmb_QuickMenu_scren_OnKeyDown" });
    }
};

scwin.file_OnClick = function() {
    try {
        scwin.selectAttach();
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDMGT42045.file_OnClick" });
    }
};

scwin.btn_delete_onclick = function() {
    try {
        scwin.delete();
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDMGT42045.btn_delete_onclick" });
    }
};

scwin.cb_system_gbn_onselchange = function() {
    try {
        scwin.listMenu();
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDMGT42045.cb_system_gbn_onselchange" });
    }
};

scwin.checkbox_1_onclick = function() {
    try {
        if (checkbox_1.checked) {
            showObj(ipt_scren_id_2, true);
            showObj(cmb_QuickMenu_scren, false);
            showObj(ipt_scren_nm, false);
            showObj(ipt_scren_id, false);
        } else {
            showObj(ipt_scren_id_2, false);
            showObj(cmb_QuickMenu_scren, true);
            showObj(ipt_scren_nm, true);
            showObj(ipt_scren_id, true);
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDMGT42045.checkbox_1_onclick" });
    }
};

///////// 4. 서브미션 콜백 영역 /////////
scwin.singleRead = async function() {
    // 공지사항 개별조회

    let getContnId = $c.win.getParent().fn_getContnId;

    let screnID = getContnId();

    const sbmOptions = {
        id : "sbm_trs_Read",
        action : "/scren.do",
        ref : "dts_NoticeContentSingle,dts_fileList",
        target : "trs_Read=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
};

scwin.delete = async function() {
    // 공지사항 삭제

    let rtn = confirm('내용을 삭제 하시겠습니까?');
    if (rtn === 1) // [확인] 버튼이 눌려졌을 경우

    {

        // dts_NoticeDelete.setDataHeader(); // W-Craft 주석처리 및 필요시 asis 파라미터 확인 
        dts_NoticeDelete.insertRow();
        dts_NoticeDelete.setCellData(1, "CONTN_ID", scwin.contnId);
        dts_NoticeDelete.setCellData(1, "NOTI_OBJ_SYS_TP_CD", scwin.objTpCd);

        let getContnId = $c.win.getParent().fn_getContnId;

        let screnID = getContnId();

        const sbmOptions = {
            id : "sbm_trs_Delete",
            action : "/scren.do",
            ref : "dts_NoticeDelete",
            target : "trs_Delete=body.content",
            isProcessMsg : false
        };

        const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    }
};

scwin.setIrInfoHeader = async function() {
    // CUD용 Header
    const sbmOptions = {
        id : "sbm_dts_noticeInfo",
        action : "/gauceSystemierAdaptor.do",
        ref : "",
        target : "dts_noticeInfo=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);

    dts_noticeInfo.insertRow();
};

scwin.code1Sync = async function() {
    const sbmOptions = {
        id : "sbm_MxDataSet_code1",
        action : "/scren.do",
        ref : "",
        target : "MxDataSet_code1=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);

};

scwin.listMenu = async function() {
    const cbSystemGbnValue = MxDataSet_code1.getCellData((cb_system_gbn.getSelectedIndex() + 1), "CD_VAL");
    const sbmOptions = {
        id : "sbm_dts_menu",
        action : "/topmenu.do",
        ref : "",
        target : "dts_menu=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);

    const sbmOptions2 = {
        id : "sbm_topmenusearch",
        action : "/topmenu.do",
        ref : "",
        target : "topmenusearch=body.content",
        isProcessMsg : false
    };

    const sbmRtn2 = await $c.sbm.executeDynamic(sbmOptions2);

};

///////// 5. 일반/업무 함수 영역 /////////
scwin.update = function() {
    // 공지사항 수정

    let rtn = confirm('위사항을 수정 하시겠습니까?');
    if (rtn === 1) // [확인] 버튼이 눌려졌을 경우

    {
        dts_NoticeContentSingle.setCellData(1, "NOTI_OBJ_SYS_TP_CD", $c.cp.valueOfIndex(cb_system_gbn, "VALUE", cb_system_gbn.getSelectedIndex()));
        let url1 = "/scren.do?method=modifyHelpContent" + "&SCREN_ID=" + "ULDMGT42045.gfm" + "&V_SCREN_ID=" + scwin.contnId + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01 + "&FILE_NM=" + dts_fileList.getCellData(0, "filename");
        trs_Update.Action = encodeURI(url1);
        // trs_Update.Action="/scren.do?method=modifyHelpContent"+"&SCREN_ID=" + vScrenID+"&V_SCREN_ID=" + contnId;
        // trs_Update.KeyName="toinb_dataid4";
        // TODO Stage2: Gauce 통신(DataID/KeyValue/Post) — executeDynamic 재설계 필요(규칙 12/16)
        trs_Update.KeyValue = "JSP(I:pInput1=dts_NoticeContentSingle,I:pFile1=dts_fileList)";

        // TODO Stage2: Gauce 통신(DataID/KeyValue/Post) — executeDynamic 재설계 필요(규칙 12/16)
        trs_Update.Post();
    }
};

scwin.save = function() {
    // 공지사항 등록
    if (cb_system_gbn.getSelectedIndex() <= 0) {
        alert("시스템을 선택하세요");
        cb_system_gbn.focus();
        return;
    }
    if (checkbox_1.checked) {
        ipt_scren_id.setValue(ipt_scren_id_2.getValue());
    }
    if (ipt_scren_id.getValue() === '') {
        alert("화면을 선택하세요");
        cmb_QuickMenu_scren.focus();
        return;
    }
    if (txb_ATTACH_FILE_NM.getValue() === '') {
        alert("첨부파일을 선택하세요");
        file.focus();
        return;
    }
    let url1 = "/scren.do?method=helpNoticeContent" + "&SCREN_ID=" + "ULDMGT42045.gfm" + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01 + "&FILE_NM=" + dts_fileList.getCellData(0, "filename");
    trs_Save.Action = encodeURI(url1);
    // TODO Stage2: Gauce 통신(DataID/KeyValue/Post) — executeDynamic 재설계 필요(규칙 12/16)
    trs_Save.KeyValue = "JSP(I:pInput=dts_noticeInfo,I:pFile1=dts_fileList)";
    // dts_noticeInfo.NameValue(1,"NOTI_OBJ_SYS_TP_CD") = cb_system_gbn.ValueOfIndex("VALUE", cb_system_gbn.Index);
    dts_noticeInfo.setCellData(1, "NOTI_OBJ_SYS_TP_CD", MxDataSet_code1.getCellData((cb_system_gbn.getSelectedIndex() + 1), "CD_VAL"));

    // TODO Stage2: Gauce 통신(DataID/KeyValue/Post) — executeDynamic 재설계 필요(규칙 12/16)
    trs_Save.Post();
    dts_fileList.removeAll();
    dts_fileList.insertRow();
    setObjectValue(txb_ATTACH_FILE_NM, '');
};

// 파일 다운로드
scwin.filedown = function(attach_seq) {
    location.href = "/filedownload.do?SCREN_ID=" + "ULDMGT42045.gfm" + "&gubun=35";
};

scwin.checkMaxLength1 = function(obj, size, lbl) {
    let overLen = eval($c.str.getByteLength(obj.value) - size);
    if (overLen > 0) {
        alert("[ " + lbl + " ] 항목의 최대입력은 [ " + size + " ] byte 입니다.    \n\n[ " + overLen + " ] byte 를 초과하였습니다.\n\n확인하세요. ( 한글 : 2 byte  숫자,영문 : 1 byte )");
        obj.focus();
        return false;
    }
    return true;
};

scwin.checkMaxLength2 = function(obj, size, lbl) {
    let overLen = eval($c.str.getByteLength(obj.text) - size);
    if (overLen > 0) {
        alert("[ " + lbl + " ] 항목의 최대입력은 [ " + size + " ] byte 입니다.    \n\n[ " + overLen + " ] byte 를 초과하였습니다.\n\n확인하세요. ( 한글 : 2 byte  숫자,영문 : 1 byte )");
        obj.focus();
        return false;
    }
    return true;
};

scwin.selectAttach = function() {
    if (scwin.contnId !== "input") {
        dts_fileList.removeAll();
        // dts_fileList.setDataHeader(); // W-Craft 주석처리 및 필요시 asis 파라미터 확인 
        dts_fileList.insertRow();
    }
    if (file.Value === "") return;
    txb_ATTACH_FILE_NM.setValue(file.Value);
    dts_fileList.setCellData(1, "fileInfo", file.Value);
    dts_fileList.setCellData(1, "fileUrl", file.Value);
    dts_fileList.setCellData(1, "filename", file.Value);
};

// 2017-02-13 KBoY FileSizeLimit 30MB		
scwin.canUploadFile = function() {
    const maxFileSize = 1024 * 1024 * 30; // 30MB		

    const mySize = inf_find.FileInfo('size');
    if (mySize < maxFileSize) {
        return true;
    } else {
        return false;
    }
};

scwin.topmenusearchEnter = function() {
    // 2008-06-30
    // 화면검색 엔터시

// TODO Stage2: Gauce Filter() — 규칙 29 필터 재설계(setColumnFilter) 필요
// topmenusearch.Filter(); — 구 Gauce 필터(재설계 시 setColumnFilter 적용)

cmb_QuickMenu_scren.setSelectedIndex(-1);
    cmb_QuickMenu_scren.trigger("onclick");
};

scwin.gform_onload = async function() {
    showObj(ipt_scren_id_2, false);
    scwin.vCurDate = $c.ut.cGetToday("yyyymmdd");

    getContnId = $c.win.getParent().fn_getContnId;

    scwin.contnId = getContnId();
    if (scwin.contnId !== "input") {
        scwin.singleRead();
        dts_fileList.insertRow();
        dts_fileList.setCellData(1, "fileInfo", dts_NoticeContentSingle.getCellData(0, "SAVE_FILE_NM"));
        txb_ATTACH_FILE_NM.setValue(dts_NoticeContentSingle.getCellData(0, "SAVE_FILE_NM"));
        const sbmOptions = {
            id : "sbm_MxDataSet_code1",
            action : "/gauceSystemierAdaptor.do",
            ref : "",
            target : "MxDataSet_code1=body.content",
            isProcessMsg : false
        };

        const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);

        scwin.code1Sync();
        const cb_system_gbn_idx = $c.cp.getNameValueRow(MxDataSet_code1, "CD_VAL", dts_NoticeContentSingle.getCellData(0, "NOTI_OBJ_SYS_TP_CD"));
        // var cb_system_gbn_idx = cb_system_gbn.IndexOfColumn("value", dts_NoticeContentSingle.NameString(1,"NOTI_OBJ_SYS_TP_CD"));
        // cb_system_gbn.Index = cb_system_gbn_idx;
        cb_system_gbn.setSelectedIndex((cb_system_gbn_idx - 1));
        showObj(cmb_QuickMenu_scren, false);
        cb_system_gbn.setDisabled(true);
        showObj(checkbox_1, false);
    } else {
        cb_system_gbn.setDisabled(false);
        // dts_fileList.setDataHeader(); // W-Craft 주석처리 및 필요시 asis 파라미터 확인 
        dts_fileList.insertRow();
        scwin.setIrInfoHeader();
        showObj(btn_delete, false);

        // 메뉴리스트 조회
        topmenusearch.dataid = "/gauceSystemierAdaptor.do?method=getGauceDataHeader&messageId=topmenu";

        topmenusearch.reset(); // 2008-06-30 추가

        dts_menu.dataid = "/gauceSystemierAdaptor.do?method=getGauceDataHeader&messageId=topmenu";

        dts_menu.reset();
        // fn_list_menu();	
        userName.setValue(js_emp_nm);
        // cb_system_gbn.ResetData(); 

        const sbmOptions = {
            id : "sbm_MxDataSet_code1",
            action : "/gauceSystemierAdaptor.do",
            ref : "",
            target : "MxDataSet_code1=body.content",
            isProcessMsg : false
        };

        const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);

        scwin.code1Sync();
    }
    cmb_QuickMenu_scren.setSelectedIndex(-1);
};
